import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] s = System.in.readAllBytes();
        int n = s.length;
        while (n > 0 && s[n - 1] == '\n') n--;
        byte[] st = new byte[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            byte c = s[i];
            if (top > 0) {
                byte t = st[top - 1];
                if ((t == 'A' && c == 'B') || (t == 'B' && c == 'A') || (t == 'C' && c == 'D') || (t == 'D' && c == 'C')) {
                    top--;
                    continue;
                }
            }
            st[top++] = c;
        }
        BufferedOutputStream out = new BufferedOutputStream(System.out);
        out.write(st, 0, top);
        out.write('\n');
        out.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

func main() {
	s, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	n := len(s)
	for n > 0 && s[n-1] == '\n' {
		n--
	}
	st := make([]byte, 0, n+1)
	for _, c := range s[:n] {
		if k := len(st); k > 0 {
			t := st[k-1]
			if (t == 'A' && c == 'B') || (t == 'B' && c == 'A') || (t == 'C' && c == 'D') || (t == 'D' && c == 'C') {
				st = st[:k-1]
				continue
			}
		}
		st = append(st, c)
	}
	st = append(st, '\n')
	os.Stdout.Write(st)
}
